procedure bubblesort (n);
var i,j: index; temp : item;
begin
    for i:=1 to n-1 do  //this will do n-1 comparisons for n elements
        if A[i] > A[i+1] then 
        begin
            temp := A[i];
            A[i] := A[i+1];
            A[i+1] := temp;
        end;
    bubblesort (n-1)    //this will decrease the size by 1 because 
&nbsp;                         in bubble sort in every iteration one element 
                         which is greatest reach to the last, so decrease
                          size to get next greatest  
end

